INSERT INTO ilb_ehr_convergence_feature(feature_code,feature_name,interpretation_limit) VALUES
('VISUALIZATION','Mental imagery','Imagery exercises can be compared; shared imagery does not prove energy transfer or a common mechanism.'),
('PRAYER','Prayer and invocation','Religious language and prayer have different meanings across traditions. They cannot be treated as identical interventions.'),
('SOUND','Sound and vocalization','Audible sound is measurable. Claims about subtle resonance or disease effects require separate tests.'),
('OBJECTS','Objects and instruments','Forks, crystals and geometric objects differ physically; their presence does not establish a shared therapeutic action.'),
('REPETITION','Repeated personal practice','Repeated exposure may affect habits or expectations. Frequency alone does not identify an effective ingredient.')
