-- Public teaching review only; no clinical validation or treatment approval.
CREATE TABLE IF NOT EXISTS ilb_ehr_process_review (
practice_code VARCHAR(64) PRIMARY KEY,
source_status ENUM('OUTLINE_AVAILABLE','IDENTITY_ONLY') NOT NULL,
delivery_scope ENUM('SELF','OTHER','SELF_AND_OTHER','UNSPECIFIED') NOT NULL,
process_outline TEXT NOT NULL,
sequence_gap TEXT NOT NULL,
source_url TEXT NOT NULL,
source_locator VARCHAR(255) NOT NULL,
source_checked_on DATE NOT NULL,
clinical_review_status ENUM('NOT_REVIEWED') NOT NULL DEFAULT 'NOT_REVIEWED',
FOREIGN KEY(practice_code) REFERENCES ilb_ehr_practice(practice_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ON DUPLICATE KEY UPDATE source_status=VALUES(source_status),delivery_scope=VALUES(delivery_scope),process_outline=VALUES(process_outline),sequence_gap=VALUES(sequence_gap),source_url=VALUES(source_url),source_locator=VALUES(source_locator),source_checked_on=VALUES(source_checked_on);

ON DUPLICATE KEY UPDATE feature_name=VALUES(feature_name),interpretation_limit=VALUES(interpretation_limit);
ON DUPLICATE KEY UPDATE action_text=VALUES(action_text),source_url=VALUES(source_url),source_locator=VALUES(source_locator),delivery_scope=VALUES(delivery_scope),component_status=VALUES(component_status),limitation_text=VALUES(limitation_text),source_checked_on=VALUES(source_checked_on);
